import novamind_api as nm
def q(sql):
    try: return nm.query(sql)['rows']
    except Exception as e: return [{"ERR": str(e)}]

print("=== ISSUES by status ===")
for r in q("SELECT status, COUNT(*) n FROM issues GROUP BY status"): print(r)
print("\n=== OPEN issues by group ===")
for r in q("SELECT group_id, COUNT(*) n, AVG(days_open) avgdays, MAX(days_open) maxdays FROM issues WHERE status!='resolved' GROUP BY group_id"): print(r)
print("\n=== Open issues age distribution ===")
for r in q("SELECT days_open, COUNT(*) n FROM issues WHERE status!='resolved' GROUP BY days_open ORDER BY days_open"): print(r)
print("\n=== Issues opened per day last 10d ===")
for r in q("SELECT open_day, COUNT(*) n FROM issues WHERE open_day>=18 GROUP BY open_day ORDER BY open_day"): print(r)
print("\n=== Resolution types lifetime ===")
for r in q("SELECT resolution_type, COUNT(*) n FROM issues WHERE status='resolved' GROUP BY resolution_type"): print(r)

print("\n=== S2 subs detail ===")
for r in q("SELECT plan, status, COUNT(*) n, AVG(effective_price) ep, AVG(listed_price) lp FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE c.group_id='S2' GROUP BY plan,status"): print(r)

print("\n=== When did S2 subs convert? ===")
for r in q("SELECT start_day, plan, status FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE c.group_id='S2' AND s.status='subscribed' ORDER BY start_day"): print(r)

print("\n=== Subs by group (active) & avg effective price ===")
for r in q("SELECT c.group_id, COUNT(*) n, AVG(s.effective_price) ep FROM subscriptions s JOIN customers c ON s.customer_id=c.customer_id WHERE s.status='subscribed' GROUP BY c.group_id"): print(r)

