    print(" cols:", list(r.keys()))

print("\n== SATISFACTION dist (if col exists) ==")
for col in ['satisfaction','satisfaction_score','sat']:
    rr = q(f"SELECT c.group_id g, ROUND(AVG(s.{col}),3) avg_sat, MIN(s.{col}) mn FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' GROUP BY c.group_id")
