except Exception as e: print("  ERR", str(e)[:150])

print("\n== research_group cost docs ==")
try:
    import json
    d = json.load(open('docs/api/market.json'))
    print(json.dumps(d, indent=0)[:1200])
except Exception as e: print("ERR", e)
