import novamind_api as nm
def q(sql): return nm.query(sql)['rows']
day = nm.vars.current_day
print(f"===== WK6 DIAG @ Day {day} =====")

# Group insights: channel effectiveness + estimates for S1, S2, S3
for g in ['S1','S2','S3']:
    try:
        gi = nm.market.get_group_insights(group_id=g)
        print(f"\n--- {g} insights ---")
        est = gi.get('estimates', gi)
        print("  estimates:", est)
        if 'ad_effectiveness' in gi: print("  ad_eff:", gi['ad_effectiveness'])
        if 'channel_effectiveness' in gi: print("  chan_eff:", gi['channel_effectiveness'])
    except Exception as e:
        print(f"  {g} ERR: {e}")

# Issue age distribution
print("\n--- Open issue age (day-open_day) ---")
for r in q(f"SELECT (CASE WHEN {day}-open_day<=1 THEN '0-1d' WHEN {day}-open_day<=3 THEN '2-3d' WHEN {day}-open_day<=7 THEN '4-7d' ELSE '8+d' END) age, COUNT(*) n FROM issues WHERE resolved_day IS NULL GROUP BY age"):
    print(f"  {r['age']:6} {r['n']}")
print("  resolved last 7d by type:")
for r in q(f"SELECT resolution_type rt, COUNT(*) n, ROUND(AVG(resolved_day-open_day),2) avg_age FROM issues WHERE resolved_day>{day-7} GROUP BY resolution_type"):
    print(f"    {r['rt']}: {r['n']} avg_age={r['avg_age']}d")

# Billing detail: first vs recurring this week
print("\n--- Subscription payments last 7d (by amount) ---")
for r in q(f"SELECT ROUND(amount,0) amt, COUNT(*) n FROM ledger WHERE day>{day-7} AND category='subscription_payment' GROUP BY ROUND(amount,0) ORDER BY n DESC LIMIT 10"):
    print(f"    ${r['amt']}: {r['n']} payments")

# Macro conditions
print("\n--- Macro conditions (latest) ---")
for r in q("SELECT * FROM macroeconomic_conditions ORDER BY day DESC LIMIT 2"):
    print("  ", r)

# Social posts last 7d
print("\n--- Social posts last 7d ---")
try:
    posts = nm.analytics.get_social_posts(days=7, limit=30)
    for p in (posts if isinstance(posts,list) else posts.get('posts',[])):
        print(f"  [{p.get('author_type','?')}/{p.get('group_id','?')}] {str(p.get('content',''))[:140]}")
except Exception as e:
    print("  ERR", e)

# Research project status
print("\n--- Research projects ---")
try:
    for r in nm.research.list_research_projects().get('projects', []):
        print("  ", {k:r.get(k) for k in ['tier','status','quality_boost','days_remaining','cost'] if k in r})
except Exception as e:
    print("  ERR", e)

# Subscriber growth by signup day (cohort)
print("\n--- New subscribed by signup-ish (start_day) last 14d ---")
for r in q(f"SELECT start_day, COUNT(*) n FROM subscriptions WHERE status='subscribed' AND start_day>{day-14} GROUP BY start_day ORDER BY start_day"):
    print(f"    day {r['start_day']}: +{r['n']}")
